"JHS 3","gender":"female","dob":"2012-04-12"},{"hash":"$2a$10$REw.MFF548/06odRTpgBH.GN97HQrWWo/D49rl6NCgKtHkoLLJcXK","username":"DEMO-202609-293","full_name":"Nii Antwi (Demo 293)","class":"JHS 3","gender":"male","dob":"2012-05-13"},{"hash":"$2a$10$nOovZ.PLFKJLsW9vtRPuUOBb6eVVyx5vwgnVI8wesBgTF43nZ8ZDW","username":"DEMO-202609-294","full_name":"Adzo Antwi (Demo 294)","class":"JHS 3","gender":"female","dob":"2012-06-14"},{"hash":"$2a$10$i3d/I7bNxMVPKBtB3vs.LuW2JLT36xCJ8eWcE1zj0TAUsAy2jdaqy","username":"DEMO-202609-295","full_name":"Yao Antwi (Demo 295)","class":"JHS 3","gender":"male","dob":"2012-07-15"},{"hash":"$2a$10$4Y583J1VfWE58BX2lc6NH.jSH.9m03rUD7Ix8Ux6ANOjHvTQZEUoS","username":"DEMO-202609-296","full_name":"Araba Antwi (Demo 296)","class":"JHS 3","gender":"female","dob":"2012-08-16"},{"hash":"$2a$10$4r97BI/sFywEFicnax3dS.N8VLGDNURueiGjnxZWS15whn6cnydJW","username":"DEMO-202609-297","full_name":"Fiifi Antwi (Demo 297)","class":"JHS 3","gender":"male","dob":"2012-01-17"},{"hash":"$2a$10$bDLiM1WVzNpgeUz/ERoPcurkzACWM82zMb36e1lv5WG5yapLsyCZq","username":"DEMO-202609-298","full_name":"Efua Antwi (Demo 298)","class":"JHS 3","gender":"female","dob":"2012-02-18"},{"hash":"$2a$10$A2d2DeZ7lNl2BmUONy11YerPs51mp4OgB0SkAvU2mPw3AyuWQeiDy","username":"DEMO-202609-299","full_name":"Kobina Antwi (Demo 299)","class":"JHS 3","gender":"male","dob":"2012-03-19"},{"hash":"$2a$10$EwEmmZRX8aYTOK44.7.qQOr4y3th.2S1uPwEqwoeNSG2ebScgR31m","username":"DEMO-202609-300","full_name":"Dede Antwi (Demo 300)","class":"JHS 3","gender":"female","dob":"2012-04-20"}]$pupils$::jsonb;
BEGIN
  SELECT sc.id INTO target_school FROM schools sc
    WHERE sc.id=1 AND sc.is_active AND EXISTS (
      SELECT 1 FROM school_settings ss WHERE ss.school_id=sc.id
        AND ss.name='OUR WORLD MODEL SCHOOL' AND ss.short_name='BFBS'
    );
  IF target_school IS NULL THEN
    RAISE NOTICE 'Skipping school-specific demo data: target school not found.';
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock(71002, target_school);
  SELECT count(*) INTO existing_count FROM users
    WHERE school_id=target_school AND username LIKE 'DEMO-202609-%';
  IF existing_count > 0 THEN
    IF existing_count=300 AND (SELECT count(*) FROM students s JOIN users u ON u.id=s.user_id
      WHERE s.school_id=target_school AND u.school_id=target_school
        AND s.student_code=u.username AND u.username LIKE 'DEMO-202609-%'
        AND u.role='student' AND u.full_name LIKE '%(Demo %)')=300 THEN
      RAISE NOTICE 'Demo batch already exists; accounts and passwords left unchanged.';
      RETURN;
    END IF;
    RAISE EXCEPTION 'Demo username collision or incomplete batch; no records changed.';
  END IF;
  IF EXISTS(SELECT 1 FROM students WHERE school_id=target_school AND student_code LIKE 'DEMO-202609-%') THEN
    RAISE EXCEPTION 'Demo student code collision; no records changed.';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(subject_data) LOOP
    subject_key := NULL;
    SELECT id INTO subject_key FROM subjects
      WHERE school_id=target_school AND deleted_at IS NULL AND lower(name) IN
        (SELECT lower(value) FROM jsonb_array_elements_text(item->'aliases')) ORDER BY id LIMIT 1;
    IF subject_key IS NULL THEN
      INSERT INTO subjects(school_id,name,code,type) VALUES(target_school,item->>'name',item->>'code','core') RETURNING id INTO subject_key;
    END IF;
    subject_map := subject_map || jsonb_build_object(item->>'name',subject_key);
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(class_data) LOOP
    INSERT INTO academic_stages(name) VALUES(item->>'stage') ON CONFLICT(name) DO NOTHING;
    SELECT id INTO stage_key FROM academic_stages WHERE name=item->>'stage';
    class_key := NULL;
    SELECT id INTO class_key FROM classes
      WHERE school_id=target_school AND deleted_at IS NULL AND lower(name) IN
        (SELECT lower(value) FROM jsonb_array_elements_text(item->'aliases')) ORDER BY id LIMIT 1;
    IF class_key IS NULL THEN
      INSERT INTO classes(school_id,name,level,stage_id,level_number,section,capacity)
        VALUES(target_school,item->>'name',item->>'stage',stage_key,(item->>'level')::int,'',40)
        RETURNING id INTO class_key;
    END IF;
    class_map := class_map || jsonb_build_object(item->>'name',class_key);
    FOR subject_name IN SELECT value FROM jsonb_array_elements_text(item->'subjects') LOOP
      subject_key := (subject_map->>subject_name)::int;
      IF EXISTS(SELECT 1 FROM class_subjects WHERE class_id=class_key AND subject_id=subject_key AND deleted_at IS NOT NULL) THEN
        RAISE EXCEPTION 'Archived class-subject collision; review before adding demo records.';
      END IF;
      INSERT INTO class_subjects(school_id,class_id,subject_id)
        VALUES(target_school,class_key,subject_key) ON CONFLICT(class_id,subject_id) DO NOTHING;
    END LOOP;
  END LOOP;
  FOR pupil IN SELECT value FROM jsonb_array_elements(pupil_data) LOOP
    INSERT INTO users(school_id,role,username,password_hash,full_name,must_change_password)
      VALUES(target_school,'student',pupil->>'username',pupil->>'hash',pupil->>'full_name',true)
      RETURNING id INTO user_key;
    INSERT INTO students(school_id,user_id,student_code,class_id,dob,gender,qr_token,status)
      VALUES(target_school,user_key,pupil->>'username',(class_map->>(pupil->>'class'))::int,
        (pupil->>'dob')::date,pupil->>'gender',gen_random_uuid()::text,'active');
  END LOOP;
  INSERT INTO audit_logs(school_id,actor_label,action,summary,metadata)
    VALUES(target_school,'School demo setup','demo.students_created',
      'Added 300 fictional demo students across 14 levels, with class subjects and individual temporary passwords.',
      '{"batch":"DEMO-202609","students":300,"levels":14}'::jsonb);
END $demo$;
